docker exec -i pocketos-db psql -U pocketos -d pocketos -c "
select schemaname, tablename, indexname, indexdef from pg_indexes
where schemaname in ('production','staging') order by tablename, indexname, schemaname;" 2>&1
echo "=== views/matviews/functions/triggers/types ==="
docker exec -i pocketos-db psql -U pocketos -d pocketos -c "
select table_schema, table_name from information_schema.views where table_schema in ('production','staging');
select n.nspname, p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('production','staging');
select n.nspname, t.tgname, c.relname from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('production','staging') and not t.tgisinternal;
select n.nspname, t.typname from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('production','staging') and t.typtype='e';" 2>&1

